/*
 Problem: 1520. Number of Steps to Reduce a Number in Binary Representation to One
 Language: rust
 Runtime: 0 ms (100.00%)
 Memory: 2.2 MB (12.33%)
 Tags: String, Bit Manipulation, Simulation
*/
impl Solution {
    pub fn num_steps(s: String) -> i32 {
        s.bytes().skip(1).rev().fold([0, 0], |[cnt, carry], b| {
            let is_odd = (b - b'0') as i32 + carry & 1;
            [cnt + 1 + is_odd, carry | is_odd]
        }).iter().sum()
    }
}

/*
 Problem: 1520. Maximum Number of Non-Overlapping Substrings
 Language: cpp
 Runtime: 3 ms (94.67%)
 Memory: 23 MB (98.56%)
 Tags: Hash Table, String, Greedy, Sorting
*/
class Solution {
public:
    vector<string> maxNumOfSubstrings(string s) {
        int n = s.size();
        vector<int> first(26, n), last(26, -1);

        for (int i = 0; i < n; ++i) {
            int c = s[i] - 'a';
            first[c] = min(first[c], i);
            last[c] = i;
        }

        vector<pair<int, int>> intervals;

        for (int c = 0; c < 26; ++c) {
            if (last[c] == -1)
                continue;

            int l = first[c];
            int r = last[c];
            bool ok = true;

            for (int i = l; i <= r; ++i) {
                int x = s[i] - 'a';

                if (first[x] < l) {
                    ok = false;
                    break;
                }

                r = max(r, last[x]);
            }

            if (ok)
                intervals.push_back({l, r});
        }

        sort(intervals.begin(), intervals.end(), [](auto& a, auto& b) {
            if (a.second != b.second)
                return a.second < b.second;
            return a.first > b.first;
        });

        vector<string> ans;
        int end = -1;

        for (auto [l, r] : intervals) {
            if (l > end) {
                ans.push_back(s.substr(l, r - l + 1));
                end = r;
            }
        }

        return ans;
    }
};
